import { createDedicatedOrgPg } from '@papercusp/db-org';
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const hash = x => createHash('sha256').update(x).digest('hex');
const started = Date.now();
const sourcePath = 'packages/operator-core/lib/search/session-ingest.ts';
const source = readFileSync(sourcePath, 'utf8');
const expectedSource = '81276d349520ea93952d19232ede4a677c75a23783984d3b12215177f4395789';
const receipt = { schemaVersion:'p008-current-owner-density-v1', workItem:'WI-10002830', startedAt:new Date(started).toISOString(), sourcePath, sourceSha256:hash(source), requestedSessions:2985, constructedInputs:true, results:[], clientClosed:false };
if (receipt.sourceSha256 !== expectedSource) throw new Error('Source fingerprint changed; inspect before measuring');
const { sql } = createDedicatedOrgPg('p008-density-fire102', { max:1 });
const selection = "SELECT DISTINCT ON(session_id) session_id, owner FROM harness_shared.session_turns WHERE workspace_id='default' AND source_kind='claude' AND owner IS NOT NULL ORDER BY session_id,turn_idx LIMIT 2985";
const density = `WITH resolved AS MATERIALIZED (SELECT * FROM UNNEST($1::text[],$2::text[]) AS r(session_id,owner)), per_session AS MATERIALIZED (SELECT r.session_id, count(t.turn_idx)::bigint AS matched_turns, count(t.turn_idx) FILTER (WHERE t.owner IS DISTINCT FROM r.owner)::bigint AS owner_mismatches, count(t.turn_idx) FILTER (WHERE t.owner IS NULL)::bigint AS owner_nulls FROM resolved r LEFT JOIN harness_shared.session_turns t ON t.workspace_id='default' AND t.source_kind='claude' AND t.session_id=r.session_id GROUP BY r.session_id) SELECT count(*)::int AS sessions, sum(matched_turns)::bigint AS matched_turns, min(matched_turns)::bigint AS min_turns, percentile_disc(0.5) WITHIN GROUP(ORDER BY matched_turns) AS median_turns, percentile_disc(0.9) WITHIN GROUP(ORDER BY matched_turns) AS p90_turns, max(matched_turns)::bigint AS max_turns, sum(owner_mismatches)::bigint AS owner_mismatches, sum(owner_nulls)::bigint AS owner_nulls, count(*) FILTER(WHERE owner_mismatches>0)::int AS sessions_with_mismatch, count(*) FILTER(WHERE matched_turns=0)::int AS sessions_without_turns FROM per_session`;
receipt.selectionSha256=hash(selection); receipt.densitySha256=hash(density);
try {
  await sql.begin('isolation level repeatable read read only', async tx => {
    receipt.stage='set-bounds';
    await tx.unsafe("SET LOCAL statement_timeout='5s'");
    await tx.unsafe("SET LOCAL lock_timeout='1s'");
    receipt.identity=(await tx.unsafe("SELECT pg_backend_pid() AS pid,current_database() AS database,current_setting('transaction_read_only') AS read_only,current_setting('statement_timeout') AS statement_timeout,current_setting('lock_timeout') AS lock_timeout,current_setting('transaction_isolation') AS isolation,current_setting('server_version_num') AS server_version_num"))[0];
    if(receipt.identity.read_only!=='on'||receipt.identity.statement_timeout!=='5s'||receipt.identity.lock_timeout!=='1s') throw new Error('Bounds verification failed');
    receipt.stage='select-constructed-map';
    let t=Date.now(); const rows=await tx.unsafe(selection); receipt.selectionElapsedMs=Date.now()-t;
    receipt.selectedRows=rows.length; receipt.uniqueIds=new Set(rows.map(r=>r.session_id)).size;
    if(rows.length!==2985 || receipt.uniqueIds!==2985) throw new Error('Constructed map cardinality did not match requested scope');
    const ids=rows.map(r=>r.session_id), owners=rows.map(r=>r.owner);
    receipt.paramsSha256=hash(JSON.stringify([ids,owners]));
    receipt.stage='density-count';
    t=Date.now(); const result=await tx.unsafe(density,[ids,owners]);
    receipt.results.push({scope:'current constructed map; original natural-query values unrecovered',elapsedMs:Date.now()-t,...result[0]});
    receipt.stage='read-only-transaction-complete';
  });
  receipt.status='ok';
} catch(error) { receipt.status='error'; receipt.error={code:error.code??null,message:error.message}; }
finally { try { await sql.end({timeout:5}); receipt.clientClosed=true; } catch(error) {receipt.cleanupError=error.message;} receipt.endedAt=new Date().toISOString(); receipt.elapsedMs=Date.now()-started; }
console.log(JSON.stringify(receipt,(_,v)=>typeof v==='bigint'?String(v):v));
process.exit(receipt.status==='ok' && receipt.clientClosed ? 0:1);
